package com.example.foryou.data.local.entity

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Represents a user entity in the database.
 *
 * @property id The unique identifier for the user, auto-generated by Room.
 * @property email The user's email address, which also serves as their login username.
 * @property password The user's encrypted password.
 * @property pinCode An optional 4-digit PIN for quick access to the app.
 */
@Entity(tableName = "users")
data class User(
    @PrimaryKey(autoGenerate = true) val id: Int = 0,
    val email: String,
    val password: String,
    val pinCode: String? = null
)
